function buildPack() {
  const meetings = [];
  const topics = [];
  const decisions = [];
  const actions = [];
  const jiraIssues = [];
  let nextDecision = 11;
  let nextAction = 7;
  let nextIssue = 201;
  const pad = (value, length = 2) => String(value).padStart(length, '0');
  const stateReasons = {
    linked: 'Связь подтверждена в синтетическом демонстрационном наборе.',
    candidates: 'Найдены похожие демонстрационные задачи; соответствие объёму работы нужно подтвердить.',
    not_found: 'В доступном демонстрационном проекте совпадений не найдено; это не проверка реальной Jira.',
    not_checked: 'Существующая задача для этого действия ещё не проверялась.',
    unavailable: 'Поиск в демонстрационной Jira недоступен; наличие задачи неизвестно.',
    not_required: 'На встрече согласовали существующий контракт без отдельной реализации в ДС.',
  };

  for (const [storyIndex, story] of stories.entries()) {
    const topicId = `ds-scale-t${pad(storyIndex + 1)}`;
    const storyDecisions = [];
    const meetingIds = [];
    for (const [meetingIndex, entry] of story.meetings.entries()) {
      const id = `ds-scale-m${pad(storyIndex * 2 + meetingIndex + 1)}`;
      meetingIds.push(id);
      const participants = [...new Set(entry.lines.map(([speaker]) => speaker))].map((key) => ({ ...people[key] }));
      const transcript = entry.lines.map(([speakerKey, content], segmentIndex) => {
        const segmentId = `${id}-s${segmentIndex + 1}`;
        const elapsed = Math.round((segmentIndex + 1) * entry.duration * 60 / (entry.lines.length + 1));
        const speaker = people[speakerKey];
        const segment = { id: segmentId, time: `${pad(Math.floor(elapsed / 60))}:${pad(elapsed % 60)}`, speaker: `${speaker.name} · ${speaker.role}`, text: typeof content === 'string' ? content : content.quote || `Договорились: ${content.text} ${content.reason}` };
        if (typeof content !== 'string') {
          const record = {
            id: `DEC-${pad(nextDecision++, 3)}`, title: content.title, text: content.text, reason: content.reason, scope: content.scope,
            components: [story.component], teams: [...story.teams], platforms: [...(content.platforms || story.platforms)], topicId,
            source: { meetingId: id, segmentId }, verification: content.pending ? 'pending' : 'verified', lifecycle: 'active',
            supersedes: content.replaces === undefined ? null : storyDecisions[content.replaces].id,
            createdAt: entry.date, actionIds: [],
          };
          if (content.replaces !== undefined) storyDecisions[content.replaces].lifecycle = 'superseded';
          storyDecisions.push(record);
          decisions.push(record);
        }
        return segment;
      });
      meetings.push({
        id, title: entry.title, date: entry.date, duration: entry.duration, kind: entry.kind,
        components: [story.component], teams: [...story.teams], platforms: [...story.platforms], participants,
        summary: entry.summary, highlights: [...entry.highlights],
        processing: storyDecisions.some((item) => item.source.meetingId === id && item.verification === 'pending') ? 'review' : 'ready',
        topicIds: [topicId], transcript,
      });
    }
    topics.push({ id: topicId, title: story.title, type: story.type, confirmed: true, status: story.status,
      components: [story.component], teams: [...story.teams], platforms: [...story.platforms], meetingIds,
      firstSeen: story.meetings[0].date, attention: false, attentionReason: '' });

    for (const work of story.work) {
      const agreed = storyDecisions[work.decision];
      const actionId = `ACT-${pad(nextAction++, 3)}`;
      const createIssue = (details) => {
        const key = `DEMO-${nextIssue++}`;
        jiraIssues.push({ key, title: details.title, status: details.status || 'Открыта',
          assignee: details.assignee || 'Разработчик ДС', component: story.component,
          description: details.description, acceptance: [...details.acceptance] });
        return key;
      };
      const issueKey = work.state === 'linked' ? createIssue({ ...work, status: work.issueStatus }) : null;
      const candidateKeys = work.state === 'candidates' ? work.candidates.map(createIssue) : [];
      actions.push({
        id: actionId, title: work.title, description: work.description, acceptance: [...work.acceptance],
        topicId, decisionId: agreed.id, source: { ...agreed.source }, components: [story.component],
        teams: [...agreed.teams], platforms: [...agreed.platforms], jiraState: work.state, issueKey, candidateKeys,
        project: 'DS', assignee: work.assignee || (work.state === 'linked' ? 'Разработчик ДС' : 'Не назначен'),
        lastChecked: ['linked', 'candidates', 'not_found'].includes(work.state) ? `${story.meetings.at(-1).date}T12:00:00Z` : null,
        reason: work.reason || stateReasons[work.state],
      });
      agreed.actionIds.push(actionId);
    }
  }
  return { id: 'ds-volume-v1', meetings, topics, decisions, actions, jiraIssues };
}

export const dsScalePack = buildPack();
